#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define inline_func inline
#define register_var register
#define input_int() geti<int>()
#define input_ll() geti<ll>()
#define read_char() getchar()
#define setup_io(a) freopen(a ".in", "r", stdin); freopen(a ".out", "w", stdout)
template<typename T> inline_func bool max_check(T &x, const T &y) { return x < y ? (x = y, true) : false; }
template<typename T> inline_func bool min_check(T &x, const T &y) { return x > y ? (x = y, true) : false; }
template<typename T>
inline_func T geti() {
    register_var T x=0;
    register_var char ch=read_char();
    bool neg=false;
    while (!isdigit(ch)) {
        if (ch=='-') neg=true;
        ch=read_char();
    }
    while (isdigit(ch)) {
        x=x*10+ch-'0';
        ch=read_char();
    }
    return neg?-x:x;
}
template<typename T>
void print_num(T num, char ch=0) {
    if (num<0) {
        putchar('-');
        num=-num;
    }
    if (num>=10) print_num(num/10);
    putchar(num%10+'0');
    if (ch) putchar(ch);
}
const int MAXN=3e5+10;
int P;
int f[19][MAXN];
int inv_fact[MAXN], fact[MAXN], inv_mod[MAXN];

ll fast_pow(ll base, int exp, ll mod=1) {
    for (; exp; exp>>=1, base=base*base%mod)
        if (exp&1) mod=mod*base%mod;
    return mod;
}

void init_vals(int n) {
    fact[0]=1;
    for (int i=1; i<=n; ++i) fact[i]=1LL*fact[i-1]*i%P;
    inv_fact[n]=fast_pow(fact[n], P-2);
    for (int i=n-1; i>=0; --i) inv_fact[i]=1LL*inv_fact[i+1]*(i+1)%P;
    inv_mod[1]=1;
    for (int i=2; i<=n; ++i) inv_mod[i]=1LL*(P-P/i)*inv_mod[P%i]%P;
}

void add_mod(int &x, int y) {
    x+=y;
    if (x>=P) x-=P;
}

void sub_mod(int &x, int y) {
    x-=y;
    x-=(x>>31)*P;
}

void transform_format(int *f, int n) {
    for (int len=1; len<n; len<<=1)
        for (int i=0; i<n; i+=len<<1)
            for (int j=0; j<len; ++j)
                add_mod(f[i+j+len], f[i+j]);
}

void inverse_transform(int *f, int n) {
    for (int len=1; len<n; len<<=1)
        for (int i=0; i<n; i+=len<<1)
            for (int j=0; j<len; ++j)
                sub_mod(f[i+j+len], f[i+j]);
}

int main() {
    #ifndef ONLINE_JUDGE
    // setup_io("onmyodo");
    #endif
    int n=get_int(), k=get_int(), P=get_int();
    int ans=fast_pow(k, n, P);
    if (~n & 1) {
        int m=(int)log2(n)+1;
        init_vals(1<<m);
        for (int i=0; i<(1<<m); ++i) {
            f[popcount(i)][i]=inv_fact[i];
        }
        transform_format(f[0], 1<<m);
        static int F[20], G[20];
        for (int i=0; i<(1<<m); ++i) {
            for (int j=0; j<=m; ++j) F[j]=f[j][i];
            compute_ln(F, G, m+1);
            for (int j=0; j<=m; ++j) G[j]=1LL*G[j]*k%P;
            compute_exp(G, F, m+1);
            for (int j=0; j<=m; ++j) f[j][i]=F[j];
        }
        inverse_transform(f[popcount(n)], 1<<m);
        ans=(P+ans-1LL*f[popcount(n)][n]*fact[n]%P)%P;
    }
    print_num(ans);
    return 0;
}
